class StackUnderflowError(Exception):
    pass


def _is_number(token):
    return token.isdigit() or (
        token.startswith("-") and len(token) > 1 and token[1:].isdigit()
    )


def _pop(stack, n):
    if len(stack) < n:
        raise StackUnderflowError("Insufficient number of items in stack")
    return [stack.pop() for _ in range(n)][::-1]


def _add(stack):
    a, b = _pop(stack, 2)
    stack.append(a + b)


def _sub(stack):
    a, b = _pop(stack, 2)
    stack.append(a - b)


def _mul(stack):
    a, b = _pop(stack, 2)
    stack.append(a * b)


def _div(stack):
    a, b = _pop(stack, 2)
    if b == 0:
        raise ZeroDivisionError("divide by zero")
    q, r = divmod(a, b)
    if r and (a < 0) != (b < 0):
        q -= 1  # truncate toward zero, like Forth
    stack.append(q)


def _dup(stack):
    a = _pop(stack, 1)[0]
    stack.extend([a, a])


def _drop(stack):
    _pop(stack, 1)


def _swap(stack):
    a, b = _pop(stack, 2)
    stack.extend([b, a])


def _over(stack):
    a, b = _pop(stack, 2)
    stack.extend([a, b, a])


BUILTINS = {
    "+": _add,
    "-": _sub,
    "*": _mul,
    "/": _div,
    "dup": _dup,
    "drop": _drop,
    "swap": _swap,
    "over": _over,
}


def _compile(body, words):
    """Compile a definition body, expanding user words but keeping
    builtins and numbers as tokens so builtins can be overridden."""
    compiled = []
    for token in body:
        if token in words:
            compiled.extend(words[token])
        else:
            compiled.append(token)
    return compiled


def _execute(tokens, stack, words):
    for token in tokens:
        if _is_number(token):
            stack.append(int(token))
        elif token in words:
            _execute(words[token], stack, words)
        elif token in BUILTINS:
            BUILTINS[token](stack)
        else:
            raise ValueError("undefined operation")


def evaluate(input_data):
    stack = []
    words = {}
    for line in input_data:
        tokens = line.split()
        if tokens and tokens[0] == ":":
            name = tokens[1].lower()
            if _is_number(name):
                raise ValueError("illegal operation")
            words[name] = _compile(tokens[2:-1], words)
        else:
            _execute(tokens, stack, words)
    return stack

